import pandas as pd
import numpy as np

TARGET_COLUMN = 'target'


class DecisionTree:
    def __init__(self, max_depth=10, min_samples_split=20, min_samples_leaf=10):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.tree = None

    def _gini(self, y):
        if len(y) == 0:
            return 0.0
        p = y.mean()
        return 2 * p * (1 - p)

    def _best_split(self, X, y):
        n, d = X.shape
        best_gain = -1
        best_feat = None
        best_thresh = None
        parent_gini = self._gini(y)

        # Subsample features for speed (sqrt(d))
        n_feats = max(1, int(np.sqrt(d)))
        feat_idx = np.random.choice(d, n_feats, replace=False)

        for f in feat_idx:
            col = X[:, f]
            # Try a subset of thresholds
            percentiles = np.percentile(col, np.linspace(5, 95, 20))
            thresholds = np.unique(percentiles)
            for t in thresholds:
                left = y[col <= t]
                right = y[col > t]
                if len(left) < self.min_samples_leaf or len(right) < self.min_samples_leaf:
                    continue
                gain = parent_gini - (len(left) * self._gini(left) + len(right) * self._gini(right)) / n
                if gain > best_gain:
                    best_gain = gain
                    best_feat = f
                    best_thresh = t

        return best_feat, best_thresh

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < self.min_samples_split or self._gini(y) < 1e-8:
            return {'leaf': True, 'val': int(y.mean() >= 0.5)}

        feat, thresh = self._best_split(X, y)
        if feat is None:
            return {'leaf': True, 'val': int(y.mean() >= 0.5)}

        mask = X[:, feat] <= thresh
        left = self._build(X[mask], y[mask], depth + 1)
        right = self._build(X[~mask], y[~mask], depth + 1)
        return {'leaf': False, 'feat': feat, 'thresh': thresh, 'left': left, 'right': right}

    def fit(self, X, y):
        self.tree = self._build(X, y, 0)

    def _predict_one(self, x, node):
        if node['leaf']:
            return node['val']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        return self._predict_one(x, node['right'])

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])


class RandomForest:
    def __init__(self, n_trees=50, max_depth=12, min_samples_split=20, min_samples_leaf=10):
        self.n_trees = n_trees
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.min_samples_leaf = min_samples_leaf
        self.trees = []

    def fit(self, X, y):
        n = len(X)
        self.trees = []
        for i in range(self.n_trees):
            np.random.seed(i)
            idx = np.random.choice(n, n, replace=True)
            tree = DecisionTree(
                max_depth=self.max_depth,
                min_samples_split=self.min_samples_split,
                min_samples_leaf=self.min_samples_leaf
            )
            tree.fit(X[idx], y[idx])
            self.trees.append(tree)

    def predict(self, X):
        preds = np.array([t.predict(X) for t in self.trees])
        return (preds.mean(axis=0) >= 0.5).astype(int)


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Random forest classifier."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].values.astype(np.float64)
    y_train = train[TARGET_COLUMN].values.astype(np.float64)
    X_test = test[feature_cols].values.astype(np.float64)

    rf = RandomForest(n_trees=30, max_depth=10, min_samples_split=20, min_samples_leaf=10)
    rf.fit(X_train, y_train)
    preds = rf.predict(X_test)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)

